export fn kth_lexicographic_permutation(v:[*]const i64,n:usize)i64{if(n!=2)return -1;var k=v[0];const m=v[1];if(m<2 or m>9 or k<0)return -1;var fact:i64=1;for(2..@as(usize,@intCast(m))+1)|i|{fact*=@intCast(i);}if(k>=fact)return -1;var a:[9]i64=@splat(0);for(0..@as(usize,@intCast(m)))|i|{a[i]=@intCast(i);}var code=m;var b:usize=@intCast(m-1);while(b>0):(b-=1){var f:i64=1;for(2..b+1)|j|{f*=@intCast(j);}const idx:usize=@intCast(@divTrunc(k,f));k=@rem(k,f);code=code*10+a[idx]+1;var j=idx;while(j<b):(j+=1){a[j]=a[j+1];}}return code*10+a[0]+1;}
